/**
 * PUBLIC ID REGISTRY — stable question IDs of the Noos ecosystem (RAN-{EXAM}-{SEQ}).
 *
 * AUTO-GENERATED by `bun scripts/generate-manifest.ts --assign` — but SEMANTICALLY
 * FROZEN once published:
 *  - A published publicId is NEVER renamed and NEVER recycled.
 *  - New questions are APPENDED with the next free sequence (the --assign flag does
 *    exactly that and nothing else — it never renumbers existing entries).
 *  - A removed question keeps its entry here (epitaph) so the number is never
 *    reused; the manifest reports it as a warning.
 *  - Typo fixes keep the ID (contentVersion bumps in the question data); a
 *    rewrite gets a NEW ID appended, with the old one kept as its
 *    alias/predecessor.
 */
export interface IdRegistryEntry {
  key: string;
  publicId: string;
}

